import React, { createContext, useContext, useEffect, useRef } from 'react';
import type { RefObject } from 'react';
import { useDisclosure } from '@chakra-ui/react';
import { useLocation } from 'react-router-dom';
import logger from '@salesforce/retail-react-app/app/utils/logger-instance';
import { CartDrawerContainer } from 'app/pages/cart/cartDrawerContainer';

/*
 * SFCC-11 plan step 9 (final commit) — mirrors the shape of base's own
 * `use-add-to-cart-modal.js` (a state-builder hook + a Context Provider + a Context-reading
 * hook), but simpler in one real, verified way: unlike base's modal, this drawer takes no
 * "item added" payload at all — across all 17 Figma state groups there is no "just added" state,
 * the drawer always renders whatever the current basket contains (see `CartDrawerContainer`'s own
 * docblock). So the shared state here is just isOpen/onOpen/onClose, and Chakra's own
 * `useDisclosure()` — already used for exactly this shape elsewhere in this codebase
 * (`useWishlistAuthDrawer.ts:126`) — is the more idiomatic choice than hand-rolling base's raw
 * `useState`.
 *
 * Two real constraints shaped this file, both found by reading the actual current code rather
 * than assumed:
 *
 * 1. **The structural trap base's own code fell into.** `AddToCartModalProvider` is mounted in
 *    base `_app` today, but `<AddToCartModal />` itself is never rendered anywhere, base or
 *    override (confirmed by grepping the whole `retail-react-app` package) — a component can't
 *    easily be both a Context's wrapper and a Context's consumer of its own child in the same
 *    render pass, and base's own code never solved that, so add-to-cart has shipped with zero
 *    visual feedback. Fixed here by making `CartDrawerProvider` itself render
 *    `CartDrawerContainer` (the file that actually renders `<ZimmCartDrawer>` with real basket
 *    content) — the Provider can never be mounted without the real UI being fed real props,
 *    because both happen in the same component body.
 *
 * 2. **`_app` needs this same live state for its own bag-icon click handler, and `_app` is the
 *    component that mounts `CartDrawerProvider`.** A component cannot consume a context it is
 *    itself providing within its own subtree — there is no ancestor `CartDrawerProvider` above
 *    `_app`'s own top-level code, only a descendant one it's about to render. `useCartDrawerState`
 *    is exported separately from `useCartDrawer` so `_app` can call the *raw* state builder
 *    directly (the same way it already calls plain `useDisclosure()` directly for its own mobile
 *    nav drawer state) and pass the resulting value into `<CartDrawerProvider value={...}>` —
 *    so `_app`'s own handler and every nested consumer (`product-view`) always observe the
 *    identical live state, never two independent copies. `useCartDrawer()` (the Context reader)
 *    is for every other consumer, which — unlike `_app` — genuinely is a descendant of the
 *    Provider.
 */

export type CartDrawerContextValue = {
  /** Whether the drawer is open. */
  isOpen: boolean;
  /**
   * Opens the drawer. Pass the element that should receive focus back once the drawer closes
   * (AC10) — e.g. the real clicked `<button>`/`<IconButton>` DOM node. Mirrors
   * `useWishlistAuthDrawer.ts`'s own `handleTriggerClick` (`useWishlistAuthDrawer.ts:267-276`):
   * capture a real element at the moment of the triggering interaction, rather than reading
   * `document.activeElement` later — that file's own comment on why
   * (`useWishlistAuthDrawer.ts:268-269`) applies identically here: a mouse click does not
   * reliably focus the clicked element in every browser. Omit/pass `null`/`undefined` when no
   * trigger element is available; the previous trigger (if any) is left untouched rather than
   * cleared, so a best-effort focus target is still preferred over none.
   */
  onOpen: (trigger?: HTMLElement | null) => void;
  /** Closes the drawer. Does not clear `triggerRef` — see `handleCloseComplete` in
   *  `zimmDrawer/index.tsx`, which reads `finalFocusRef` only after the close animation
   *  finishes, i.e. strictly after `onClose` has already run. Clearing the ref here would
   *  make AC10 focus-return silently fail on every close. */
  onClose: () => void;
  /** AC10 focus-return target — whichever element was last passed to `onOpen`. Forward to
   *  `ZimmDrawer`/`CartDrawerContainer`'s `finalFocusRef` prop. Typed as `RefObject<HTMLElement>`
   *  (not `| null`) to satisfy that prop's own type — same typing precedent as
   *  `useWishlistAuthDrawer.ts`'s own `triggerRef` (`useWishlistAuthDrawer.ts:88,140`). */
  triggerRef: RefObject<HTMLElement>;
};

// Exported (not just used internally) for the same reason base exports `AddToCartModalContext`
// directly (`use-add-to-cart-modal.js:59`) — lets a test wrap a subtree with a controlled value
// via `CartDrawerContext.Provider` directly, without going through the real state builder.
export const CartDrawerContext = createContext<CartDrawerContextValue | undefined>(undefined);

/**
 * Builds the cart drawer's shared isOpen/onOpen/onClose state plus its AC10 focus-return
 * trigger ref — the raw equivalent of base's own `useAddToCartModal()`. Called exactly once, by
 * `_app`, which passes the result into `CartDrawerProvider`'s `value` prop — see this file's own
 * module docblock (constraint 2) for why `_app` needs the raw builder rather than
 * `useCartDrawer()`'s Context read.
 *
 * @returns The shared cart-drawer state — see `CartDrawerContextValue`.
 */
export const useCartDrawerState = (): CartDrawerContextValue => {
  const { isOpen, onOpen: onDisclosureOpen, onClose } = useDisclosure();
  // Typed as HTMLElement (not HTMLElement | null) so `.current` is writable below — same cast
  // and reasoning as useWishlistAuthDrawer.ts:140 (a plain `useRef<HTMLElement>(null)` would
  // infer the read-only `RefObject<HTMLElement>` overload instead of `MutableRefObject`).
  const triggerRef = useRef<HTMLElement>(null as unknown as HTMLElement);

  const onOpen = (trigger?: HTMLElement | null): void => {
    if (trigger) triggerRef.current = trigger;
    onDisclosureOpen();
  };

  // Judgement call (no AC or Figma state describes this either way — see this hook's own
  // module docblock and the PR report for the fuller reasoning): close the drawer whenever the
  // route changes, mirroring base `use-add-to-cart-modal.js`'s own `[pathname]`-keyed effect
  // (`use-add-to-cart-modal.js:603-611`) and this exact file's sibling precedent —
  // `_app/index.tsx`'s own mobile-nav drawer already closes itself the same way
  // (`_app/index.tsx`'s own `useEffect(() => { onClose(); }, [location])`, "Lets automatically
  // close the mobile navigation when the location path is changed."). Concretely load-bearing,
  // not just consistency: `ZimmCartButtonGroup`'s Checkout button (already built, SFCC-275)
  // navigates via a plain `history.push('/checkout')` with no `onClose` call of its own
  // (verified directly against `zimmCartButtonGroup/index.tsx`'s `handleCheckoutClick`), and
  // `ZimmDrawer`'s overlay is not click-through — without this effect, clicking Checkout from
  // inside the cart drawer would navigate to `/checkout` while the drawer stayed open on top of
  // it, leaving the shopper unable to see or reach the page they just navigated to.
  const { pathname } = useLocation();
  useEffect(() => {
    if (isOpen) {
      onClose();
    }
    // Deliberately keyed on pathname alone, matching use-add-to-cart-modal.js's own shape —
    // isOpen/onClose are read for their current value, not to decide when the effect re-runs.
  }, [pathname]);

  return { isOpen, onOpen, onClose, triggerRef };
};

// Stable (module-level, not per-render) no-op fallback for when no CartDrawerProvider is
// mounted above the caller — see useCartDrawer's own doc for why this degrades instead of
// throwing. `triggerRef` is a plain inert object, not a real useRef() result: nothing outside a
// real CartDrawerProvider subtree ever reads it back for a real focus call.
const FALLBACK_ONLY: CartDrawerContextValue = {
  isOpen: false,
  onOpen: () => {
    // A real shopper's page always has a CartDrawerProvider ancestor (mounted once in `_app`),
    // so reaching this in a real request is a genuine bug, not an expected path — logged so a
    // silently-broken Add to Bag button is at least observable, rather than a shopper clicking
    // it and nothing happening with no trace anywhere.
    logger.warn('useCartDrawer called with no CartDrawerProvider mounted — Add to Bag will not open the cart drawer.', {
      namespace: 'useCartDrawer',
    });
  },
  onClose: () => undefined,
  triggerRef: { current: null },
};

/**
 * Reads the shared cart-drawer state from Context. For any consumer that is a genuine descendant
 * of `CartDrawerProvider` (e.g. `product-view`) — see this file's own module docblock for why
 * `_app` itself must use `useCartDrawerState()` directly instead.
 *
 * Degrades to a stable, harmless no-op outside a Provider — the same shape `useUiCopy.ts` already
 * uses (`useContext(...) ?? FALLBACK_ONLY`) — rather than throwing. Confirmed necessary, not
 * merely convenient: `product-view/index.stories.tsx` (unmodified by this change — not in this
 * step's own manifest) wraps `ProductView`'s stories in the now-removed `AddToCartModalProvider`,
 * with no `CartDrawerProvider` in its own decorator stack, and every one of its stories renders
 * the real default `ProductView` export, which calls this hook unconditionally near its own top
 * level. A throwing `useCartDrawer` (this file's own first draft, matching `useIntl`'s
 * load-bearing/non-degrading precedent) crashes all four of that file's stories on mount, before
 * any interaction — verified live against a real running Storybook instance, not assumed (see
 * this step's own PR report). `onOpen`'s own no-op additionally logs a warning (see
 * `FALLBACK_ONLY` above) so a genuine missing-Provider bug in the real app — which should never
 * happen, since `_app` always mounts one — is still observable rather than a silent dead button.
 *
 * @returns The shared cart-drawer state — see `CartDrawerContextValue`.
 */
export const useCartDrawer = (): CartDrawerContextValue => useContext(CartDrawerContext) ?? FALLBACK_ONLY;

export type CartDrawerProviderProps = {
  /** The live state to provide — built via `useCartDrawerState()` by the one caller (`_app`)
   *  that also needs it directly for its own bag-icon click handler. Accepting it as a prop
   *  (rather than calling `useCartDrawerState()` internally) is what lets `_app` and every
   *  nested consumer share the exact same instance — see this file's own module docblock,
   *  constraint 2. */
  value: CartDrawerContextValue;
  children: React.ReactNode;
};

/**
 * Provides the shared cart-drawer state to `children` AND renders `CartDrawerContainer` — the
 * component that actually renders `<ZimmCartDrawer>` with real basket content — in the same
 * place. See this file's own module docblock, constraint 1, for why both happen together here
 * rather than leaving `CartDrawerContainer` for some other, easily-forgotten call site to mount.
 *
 * Written with `React.createElement` rather than JSX so this file can stay `.ts` (as named in
 * the SFCC-11 plan's own file manifest) — every other source file under `overrides/app/hooks/`
 * is `.ts` with no JSX in it; `useUiCopy.ts`'s own Provider is a separate `.tsx` component under
 * `overrides/app/components/uiCopyProvider/` rather than living in the hook file itself, which
 * is the established split this codebase already uses for exactly this shape. Splitting
 * `CartDrawerProvider` out the same way was the more consistent option but would have meant
 * creating a file outside this step's own manifest — flagged in the PR report, not decided
 * silently. `React.createElement(...)` has one direct precedent already in this codebase for
 * the identical reason (a `.ts` file needing to produce a React element without JSX syntax):
 * `overrides/app/components/forms/useAddressFields.test.ts:26`.
 */
export const CartDrawerProvider = ({ value, children }: CartDrawerProviderProps): React.ReactElement =>
  React.createElement(
    CartDrawerContext.Provider,
    { value },
    children,
    React.createElement(CartDrawerContainer, {
      isOpen: value.isOpen,
      onClose: value.onClose,
      // 1:1 Figma-alignment audit fix, 2026-09-22: lets CartDrawerContainer reopen this same
      // drawer once a guest's wishlist auth flow succeeds — see CartDrawerContainerProps' own
      // `onOpen` doc in cartDrawerContainer.tsx for why it's threaded through as a prop here
      // rather than that file calling useCartDrawer() directly (circular import).
      onOpen: value.onOpen,
      finalFocusRef: value.triggerRef,
    }),
  );

