449	/**
450	 * Container — the real cart-drawer content assembly (SFCC-11 plan step 4.6). See this file's own
451	 * module docblock for why this owns `useCurrentBasket()` and lives under `pages/cart/`, not
452	 * `components/`.
453	 */
454	export const CartDrawerContainer = ({ isOpen, onClose, onOpen, finalFocusRef }: CartDrawerContainerProps) => {
455	  const { data: basket, refetch: refetchBasket } = useCurrentBasket() as unknown as UseCurrentBasketReturn;
456	  const productItems: SfccBasketProductItem[] = basket?.productItems ?? [];
457	  // 1:1 Figma-alignment audit fix, 2026-09-22 (Marcel's direct call): total quantity across every
458	  // line, not `productItems.length` (distinct line count) — the value this used to be. Neither
459	  // Figma (the drawer header node renders a literal "BAG • #" placeholder, no dev annotation) nor
460	  // ZimmCartDrawer's own doc comment (an unsourced assumption from whenever it was first built)
461	  // settle which metric is correct, and Marcel's Jira token wasn't available to check the
462	  // originating ticket's AC either — so this is sourced from the current production
463	  // www.zimmermann.com site's own header behaviour instead, confirmed by Marcel directly: it
464	  // shows total quantity, not distinct products. `=== 0` below is unaffected either way — a truly
465	  // empty basket has both metrics at zero.
466	  const itemCount = productItems.reduce((total, item) => total + (item.quantity ?? 0), 0);
467	
468	  // SFCC-11 1:1 Figma-alignment audit fix, 2026-09-22: lives here, not inside CartItemsColumn —
469	  // confirmed live (not assumed) that Chakra's Drawer/Modal stops re-rendering its children once
470	  // `isOpen` goes false, rather than rendering them once more with the new value before removal,
471	  // so a reset effect inside CartItemsColumn watching its own `isOpen` prop never actually runs.
472	  // This component is never unmounted by its own `isOpen` toggling (it's the thing that HANDS
473	  // `isOpen` to ZimmCartDrawer, not something ZimmCartDrawer's own open/closed state controls),
474	  // so its effects keep running regardless of whether the drawer is visually open. See
475	  // CartItemsColumn's own doc for what this state is and why (Marcel's own direct call: clears on
476	  // close, not a timer, not the next interaction with the line).
477	  const [alreadyInWishlistItemIds, setAlreadyInWishlistItemIds] = useState<Set<string>>(new Set());
478	  useEffect(() => {
479	    if (!isOpen) setAlreadyInWishlistItemIds(new Set());
480	  }, [isOpen]);
481	  const markAlreadyInWishlist = useCallback((itemId: string) => {
482	    setAlreadyInWishlistItemIds((prev) => {
483	      const next = new Set(prev);
484	      next.add(itemId);
485	      return next;
486	    });
487	  }, []);
488	
489	  // Base `pages/cart/index.jsx`'s own real precedent for building ProductItem's `product` prop
490	  // (`{...productItem, ...productsByItemId[productItem.itemId], price: productItem.price,
491	  // quantity: ...}`, node_modules/@salesforce/retail-react-app/app/pages/cart/index.jsx) — minus
492	  // `allImages: true` on the fetch (over-fetching, and the exact parameter implicated in the
493	  // SFCC-29 outage) and minus its bundle/bonus-product/multi-location-inventory enrichment (real
494	  // complexity this epic never asked for). One correction against that same base file, found by
495	  // reading it in full rather than trusting a paraphrase: its OWN per-line lookup map
496	  // (`productsByItemId`, a second, separate useMemo) is keyed by `productItem.itemId`, but is
497	  // itself built from `products?.[productItem?.productId]` — i.e. the raw `useProducts` fetch
498	  // below is keyed by PRODUCT id, not item id, and the re-keying-by-itemId step exists there only
499	  // to support the bundle-child-inventory enrichment this container does not replicate. This
500	  // container looks the fetched product up by `productId` directly, with no intermediate re-keyed
501	  // map.
502	  // The generated `getProducts` query parameters type this SDK call resolves against
503	  // (`getProductsQueryParameters`, commerce-sdk-isomorphic) types `ids` as `Array<string>` — base
504	  // `pages/cart/index.jsx`'s own equivalent call passes a comma-joined string instead (its own
505	  // file is untyped `.jsx`, so nothing catches the mismatch there); an array is what this
506	  // TypeScript call site actually needs.
507	  const productIds = productItems.map((item) => item.productId).filter((id): id is string => Boolean(id));
508	  const { data: productsResult, isLoading: isProductsLoading } = useProducts(
509	    { parameters: { ids: productIds, perPricebook: true } },
510	    { enabled: productIds.length > 0 },
511	  );
512	  // Reshaped outside the hook call, not via a `select` option: commerce-sdk-react's own
513	  // `ApiQueryOptions` type pins `select`'s return type to the query's own raw result type
514	  // (`UseQueryOptions<DataType<Method>, unknown, DataType<Method>, ...>` — the third, `TData`,
515	  // generic is hard-coded to match the first), so a `select` reshaping into a keyed map does not
516	  // type-check here even though base's own untyped `.jsx` equivalent does exactly this via its
517	  // own `select`. A `useMemo` outside the hook achieves the identical keyed-by-product-id shape.
518	  const productsById = useMemo(
519	    () =>
520	      (productsResult?.data ?? []).reduce((acc: Record<string, ShopperProductsTypes.Product>, product) => {
521	        acc[product.id] = product;
522	        return acc;
523	      }, {} as Record<string, ShopperProductsTypes.Product>),
524	    [productsResult],
525	  );
526	
527	  /* -------------------------------------------------------------------------------------------
528	   * Pass criterion 2 — useCartMergeAndCap's render guard, this hook's second of two call sites
529	   * (the first, the post-auth callback, was wired into useWishlistAuthDrawer.ts back in step 4.2).
530	   * Keyed on `[basket]` (react-query returns a stable reference across renders where the basket
531	   * data hasn't actually changed, thanks to structural sharing) rather than on
532	   * `capBasketQuantities` itself, which useCartMergeAndCap does not memoise — a fresh function
533	   * reference every render, so including it here would re-run this effect on every render instead
534	   * of only on a real basket-state change. capBasketQuantities' own internal guards (mutation-in-
535	   * flight, already-attempted-this-version) would make an extra call harmless regardless, but
536	   * "runs on a basket-driven re-render" is this criterion's own explicit framing.
537	   * ---------------------------------------------------------------------------------------- */
538	  const { capBasketQuantities } = useCartMergeAndCap();
539	  const { notifyMaxQuantityReached } = useCartMessages();
540	  // notifyAddedToWishlist/notifyAlreadyInWishlist are NOT called from this container — verified
541	  // directly against zimmCartItemActions/index.tsx's own current code (not assumed from this
542	  // step's own plan text, which describes all three as called "by this container"): ZimmCartItemActions
543	  // already calls useCartMessages itself and fires both from its own attemptMoveToWishlist. Calling
544	  // them again here would double-fire the toast for a single successful move. notifyMaxQuantityReached
545	  // is the one function with no other call site anywhere in this codebase — genuinely this
546	  // container's own responsibility, fired below once the render guard reports a real correction.
547	  useEffect(() => {
548	    if (!basket?.basketId) return;
549	    void capBasketQuantities(basket).then((result) => {
550	      if (result.status === 'corrected') {
551	        notifyMaxQuantityReached();
552	      }
553	    });
554	  }, [basket]);
555	
556	  /* -------------------------------------------------------------------------------------------
557	   * Pass criterion 4 — the wishlist-move resume must wait for the merge-then-cap chain to settle.
558	   * See useWishlistAuthDrawer.ts's own isRegistered effect: onAuthSuccess fires synchronously,
559	   * immediately before mergeBasket.mutate(...) — so isGuest cannot simply mirror `!isRegistered`
560	   * one-for-one, or ZimmCartItemActions' resumed usePendingWishlistItem effect (keyed on
561	   * `[isGuest]`) could fire before the merge has even started.
562	   *
563	   * hasPendingPostAuthSettleRef is a ref, not React state, deliberately: useWishlistAuthDrawer()
564	   * is called (below) before this gating effect is declared, so within the SAME commit, its own
565	   * internal [isRegistered] effect runs first and calls handleAuthSuccess synchronously — a
566	   * setState there would only become visible on a LATER render (one render behind), which would
567	   * let this effect's very first run (in the same commit as the isRegistered flip) read a stale
568	   * "not yet settling" value and flip isGuestState to false immediately, before mergeBasket.mutate
569	   * has registered anything in the mutation cache. A ref mutation is visible immediately to any
570	   * code running later in the same synchronous effect-flush pass, which is exactly what this
571	   * needs. This is the same class of stale-closure trap useCartMergeAndCap.ts's own docblock
572	   * already documents fixing (a React-render-time value instead of a live read) — applied here to
573	   * the ordering between two different hooks in the same fiber rather than to a single async
574	   * closure.
575	   *
576	   * queryClient.isMutating() (a live, imperative read, taken fresh at the moment this effect body
577	   * runs) — not the reactive `isMutatingSignal` value below — is what actually decides whether to
578	   * flip isGuestState. `isMutatingSignal` (useIsMutating()) exists purely so this effect re-runs
579	   * every time the app-wide mutation count changes, giving it a fresh chance to re-check the live
580	   * value; using its own render-time value directly would reintroduce the identical stale-read
581	   * risk described above. Matches useCartMergeAndCap.ts's own documented reasoning for the same
582	   * hook pairing (queryClient.isMutating() for correctness, useIsMutating() for reactivity).
583	   * ---------------------------------------------------------------------------------------- */
584	  const { isRegistered } = useCustomerType();
585	  const [isGuestState, setIsGuestState] = useState(!isRegistered);
586	  const queryClient = useQueryClient();
587	  const isMutatingSignal = useIsMutating();
588	  const hasPendingPostAuthSettleRef = useRef(false);
589	
590	  // 1:1 Figma-alignment audit fix, 2026-09-22 (Marcel's own direct decision): re-opens the cart
591	  // once a guest's wishlist auth flow succeeds — the counterpart to openGuestWishlistDrawer
592	  // below closing it first. useWishlistAuthDrawer's own sessionStorage fallback (its own
593	  // PENDING_WISHLIST_INTENT_KEY) already guarantees onAuthSuccess fires here reliably whether
594	  // the shopper authenticated in-page (email code) or via a full-page social-IDP redirect — this
595	  // callback doesn't need to distinguish the two paths itself. No trigger element is passed to
596	  // onOpen: there's no real user click to capture at this exact moment (this fires from an auth
597	  // callback, not a click handler), so the previous trigger — whatever originally opened the
598	  // cart — is left in place as the AC10 focus-return target once the cart finally closes for
599	  // good, per onOpen's own doc ("the previous trigger... is left untouched rather than cleared").

