        initialFocusRef={wishlistAuthDrawer.emailInputRef}
      >
        <ErrorFallback>
          <ZimmAuthDrawerContent
            description={wishlistAuthDrawer.description}
            emailValue={wishlistAuthDrawer.emailValue}
            onEmailChange={wishlistAuthDrawer.onEmailChange}
            onSendCode={wishlistAuthDrawer.onSendCode}
            onSignInWithApple={wishlistAuthDrawer.onSignInWithApple}
            onSignInWithGoogle={wishlistAuthDrawer.onSignInWithGoogle}
            onCreateAccount={wishlistAuthDrawer.onCreateAccount}
            socialEnabled={wishlistAuthDrawer.isSocialEnabled}
            passwordlessEnabled={wishlistAuthDrawer.isPasswordlessEnabled}
            initialFocusRef={wishlistAuthDrawer.emailInputRef}
          />
        </ErrorFallback>
      </ZimmDrawer>
      <AuthModal {...wishlistAuthDrawer.registerModal} />
      <OtpAuth
        isOpen={wishlistAuthDrawer.isOtpAuthOpen}
        onClose={wishlistAuthDrawer.onOtpAuthClose}
        form={wishlistAuthDrawer.form}
        handleSendEmailOtp={wishlistAuthDrawer.handlePasswordlessLogin}
        handleOtpVerification={wishlistAuthDrawer.handleOtpVerification}
        hideCheckoutAsGuestButton={true}
      />
    </>
  );
};

/**
 * Container — the real cart-drawer content assembly (SFCC-11 plan step 4.6). See this file's own
 * module docblock for why this owns `useCurrentBasket()` and lives under `pages/cart/`, not
 * `components/`.
 */
export const CartDrawerContainer = ({ isOpen, onClose, onOpen, finalFocusRef }: CartDrawerContainerProps) => {
  const { data: basket, refetch: refetchBasket } = useCurrentBasket() as unknown as UseCurrentBasketReturn;
  const productItems: SfccBasketProductItem[] = basket?.productItems ?? [];
  // 1:1 Figma-alignment audit fix, 2026-09-22 (Marcel's direct call): total quantity across every
  // line, not `productItems.length` (distinct line count) — the value this used to be. Neither
  // Figma (the drawer header node renders a literal "BAG • #" placeholder, no dev annotation) nor
  // ZimmCartDrawer's own doc comment (an unsourced assumption from whenever it was first built)
  // settle which metric is correct, and Marcel's Jira token wasn't available to check the
  // originating ticket's AC either — so this is sourced from the current production
  // www.zimmermann.com site's own header behaviour instead, confirmed by Marcel directly: it
  // shows total quantity, not distinct products. `=== 0` below is unaffected either way — a truly
  // empty basket has both metrics at zero.
  const itemCount = productItems.reduce((total, item) => total + (item.quantity ?? 0), 0);

  // SFCC-11 1:1 Figma-alignment audit fix, 2026-09-22: lives here, not inside CartItemsColumn —
  // confirmed live (not assumed) that Chakra's Drawer/Modal stops re-rendering its children once
  // `isOpen` goes false, rather than rendering them once more with the new value before removal,
  // so a reset effect inside CartItemsColumn watching its own `isOpen` prop never actually runs.
  // This component is never unmounted by its own `isOpen` toggling (it's the thing that HANDS
  // `isOpen` to ZimmCartDrawer, not something ZimmCartDrawer's own open/closed state controls),
  // so its effects keep running regardless of whether the drawer is visually open. See
  // CartItemsColumn's own doc for what this state is and why (Marcel's own direct call: clears on
  // close, not a timer, not the next interaction with the line).
  const [alreadyInWishlistItemIds, setAlreadyInWishlistItemIds] = useState<Set<string>>(new Set());
  useEffect(() => {
    if (!isOpen) setAlreadyInWishlistItemIds(new Set());
  }, [isOpen]);
  const markAlreadyInWishlist = useCallback((itemId: string) => {
    setAlreadyInWishlistItemIds((prev) => {
      const next = new Set(prev);
      next.add(itemId);
      return next;
    });
  }, []);

  // Base `pages/cart/index.jsx`'s own real precedent for building ProductItem's `product` prop
  // (`{...productItem, ...productsByItemId[productItem.itemId], price: productItem.price,
  // quantity: ...}`, node_modules/@salesforce/retail-react-app/app/pages/cart/index.jsx) — minus
  // `allImages: true` on the fetch (over-fetching, and the exact parameter implicated in the
  // SFCC-29 outage) and minus its bundle/bonus-product/multi-location-inventory enrichment (real
  // complexity this epic never asked for). One correction against that same base file, found by
  // reading it in full rather than trusting a paraphrase: its OWN per-line lookup map
  // (`productsByItemId`, a second, separate useMemo) is keyed by `productItem.itemId`, but is
  // itself built from `products?.[productItem?.productId]` — i.e. the raw `useProducts` fetch
  // below is keyed by PRODUCT id, not item id, and the re-keying-by-itemId step exists there only
  // to support the bundle-child-inventory enrichment this container does not replicate. This
  // container looks the fetched product up by `productId` directly, with no intermediate re-keyed
  // map.
  // The generated `getProducts` query parameters type this SDK call resolves against
  // (`getProductsQueryParameters`, commerce-sdk-isomorphic) types `ids` as `Array<string>` — base
  // `pages/cart/index.jsx`'s own equivalent call passes a comma-joined string instead (its own
  // file is untyped `.jsx`, so nothing catches the mismatch there); an array is what this
  // TypeScript call site actually needs.
  const productIds = productItems.map((item) => item.productId).filter((id): id is string => Boolean(id));
  const { data: productsResult, isLoading: isProductsLoading } = useProducts(
    { parameters: { ids: productIds, perPricebook: true } },
    { enabled: productIds.length > 0 },
  );
  // Reshaped outside the hook call, not via a `select` option: commerce-sdk-react's own
  // `ApiQueryOptions` type pins `select`'s return type to the query's own raw result type
  // (`UseQueryOptions<DataType<Method>, unknown, DataType<Method>, ...>` — the third, `TData`,
  // generic is hard-coded to match the first), so a `select` reshaping into a keyed map does not
  // type-check here even though base's own untyped `.jsx` equivalent does exactly this via its
  // own `select`. A `useMemo` outside the hook achieves the identical keyed-by-product-id shape.
  const productsById = useMemo(
    () =>
      (productsResult?.data ?? []).reduce((acc: Record<string, ShopperProductsTypes.Product>, product) => {
        acc[product.id] = product;
        return acc;
      }, {} as Record<string, ShopperProductsTypes.Product>),
    [productsResult],
  );

  /* -------------------------------------------------------------------------------------------
   * Pass criterion 2 — useCartMergeAndCap's render guard, this hook's second of two call sites
   * (the first, the post-auth callback, was wired into useWishlistAuthDrawer.ts back in step 4.2).
   * Keyed on `[basket]` (react-query returns a stable reference across renders where the basket
   * data hasn't actually changed, thanks to structural sharing) rather than on
   * `capBasketQuantities` itself, which useCartMergeAndCap does not memoise — a fresh function
   * reference every render, so including it here would re-run this effect on every render instead
   * of only on a real basket-state change. capBasketQuantities' own internal guards (mutation-in-
   * flight, already-attempted-this-version) would make an extra call harmless regardless, but
   * "runs on a basket-driven re-render" is this criterion's own explicit framing.
   * ---------------------------------------------------------------------------------------- */
  const { capBasketQuantities } = useCartMergeAndCap();
  const { notifyMaxQuantityReached } = useCartMessages();
  // notifyAddedToWishlist/notifyAlreadyInWishlist are NOT called from this container — verified
  // directly against zimmCartItemActions/index.tsx's own current code (not assumed from this
  // step's own plan text, which describes all three as called "by this container"): ZimmCartItemActions
  // already calls useCartMessages itself and fires both from its own attemptMoveToWishlist. Calling
  // them again here would double-fire the toast for a single successful move. notifyMaxQuantityReached
  // is the one function with no other call site anywhere in this codebase — genuinely this
  // container's own responsibility, fired below once the render guard reports a real correction.
  useEffect(() => {
    if (!basket?.basketId) return;
    void capBasketQuantities(basket).then((result) => {
      if (result.status === 'corrected') {
        notifyMaxQuantityReached();
      }
    });
  }, [basket]);

  /* -------------------------------------------------------------------------------------------
   * Pass criterion 4 — the wishlist-move resume must wait for the merge-then-cap chain to settle.
   * See useWishlistAuthDrawer.ts's own isRegistered effect: onAuthSuccess fires synchronously,
   * immediately before mergeBasket.mutate(...) — so isGuest cannot simply mirror `!isRegistered`
   * one-for-one, or ZimmCartItemActions' resumed usePendingWishlistItem effect (keyed on
   * `[isGuest]`) could fire before the merge has even started.
   *
   * hasPendingPostAuthSettleRef is a ref, not React state, deliberately: useWishlistAuthDrawer()
   * is called (below) before this gating effect is declared, so within the SAME commit, its own
   * internal [isRegistered] effect runs first and calls handleAuthSuccess synchronously — a
   * setState there would only become visible on a LATER render (one render behind), which would
   * let this effect's very first run (in the same commit as the isRegistered flip) read a stale
   * "not yet settling" value and flip isGuestState to false immediately, before mergeBasket.mutate
   * has registered anything in the mutation cache. A ref mutation is visible immediately to any
   * code running later in the same synchronous effect-flush pass, which is exactly what this
   * needs. This is the same class of stale-closure trap useCartMergeAndCap.ts's own docblock
   * already documents fixing (a React-render-time value instead of a live read) — applied here to
   * the ordering between two different hooks in the same fiber rather than to a single async
   * closure.
   *
   * queryClient.isMutating() (a live, imperative read, taken fresh at the moment this effect body
   * runs) — not the reactive `isMutatingSignal` value below — is what actually decides whether to
   * flip isGuestState. `isMutatingSignal` (useIsMutating()) exists purely so this effect re-runs
   * every time the app-wide mutation count changes, giving it a fresh chance to re-check the live
   * value; using its own render-time value directly would reintroduce the identical stale-read
   * risk described above. Matches useCartMergeAndCap.ts's own documented reasoning for the same
   * hook pairing (queryClient.isMutating() for correctness, useIsMutating() for reactivity).
   * ---------------------------------------------------------------------------------------- */
  const { isRegistered } = useCustomerType();
  const [isGuestState, setIsGuestState] = useState(!isRegistered);
  const queryClient = useQueryClient();
  const isMutatingSignal = useIsMutating();
  const hasPendingPostAuthSettleRef = useRef(false);

  // 1:1 Figma-alignment audit fix, 2026-09-22 (Marcel's own direct decision): re-opens the cart
  // once a guest's wishlist auth flow succeeds — the counterpart to openGuestWishlistDrawer
  // below closing it first. useWishlistAuthDrawer's own sessionStorage fallback (its own
  // PENDING_WISHLIST_INTENT_KEY) already guarantees onAuthSuccess fires here reliably whether
  // the shopper authenticated in-page (email code) or via a full-page social-IDP redirect — this
  // callback doesn't need to distinguish the two paths itself. No trigger element is passed to
  // onOpen: there's no real user click to capture at this exact moment (this fires from an auth
  // callback, not a click handler), so the previous trigger — whatever originally opened the
  // cart — is left in place as the AC10 focus-return target once the cart finally closes for
  // good, per onOpen's own doc ("the previous trigger... is left untouched rather than cleared").

