  // Once the cart remounts, ZimmCartItemActions/usePendingWishlistItem's own existing mount-time
  // sessionStorage check (already built for the redirect case) naturally resumes the pending
  // move — nothing new needed there.
  //
  // Confirmed bug, 2026-09-23 (Marcel's direct report, live-tested): create-account's own
  // onAuthSuccess fires as part of the very same event that navigates to /account (see
  // REOPEN_AFTER_ACCOUNT_CREATION_DELAY_MS's own doc comment for why) — calling onOpen()
  // synchronously here raced that navigation and lost, every time, live-confirmed (the drawer
  // stayed closed on /account, though the resumed move itself still completed correctly once
  // manually reopened — proving this race, not the resume logic, was the actual gap). Deferred
  // by the same short delay this codebase already uses for an analogous settle-then-transition
  // case, so the navigation's own pathname-triggered close (useCartDrawer.ts) has already
  // resolved before this reopen runs, rather than the two racing in the same tick. Harmless for
  // the email-code/social-login paths too: neither navigates away, so this delay just means a
  // barely perceptible pause before a reopen that was always going to happen regardless.
  const handleAuthSuccess = useCallback(() => {
    hasPendingPostAuthSettleRef.current = true;
    setTimeout(() => onOpen(), REOPEN_AFTER_ACCOUNT_CREATION_DELAY_MS);
  }, [onOpen]);

  const wishlistAuthDrawer = useWishlistAuthDrawer({
    onAuthSuccess: handleAuthSuccess,
    intentId: CART_WISHLIST_INTENT_ID,
  });

  useEffect(() => {
    if (!isRegistered) {
      setIsGuestState(true);
      return;
    }
    // Steady-state (a shopper already registered when this container mounts) never sets the ref,
    // so `!hasPendingPostAuthSettleRef.current` is true immediately — no artificial wait for
    // someone with nothing to wait for.
    if (!hasPendingPostAuthSettleRef.current || queryClient.isMutating() === 0) {
      hasPendingPostAuthSettleRef.current = false;
      setIsGuestState(false);
    }
  }, [isRegistered, isMutatingSignal, queryClient]);

  /**
   * Opens the one shared wishlist auth drawer from any row's guest click. ZimmCartItemActions'
   * onGuestWishlistClick is `() => void` — no event to forward, because every row shares this one
   * drawer instance (ZimmCartItemActions' own docblock explicitly rejects one useWishlistAuthDrawer
   * per row). useWishlistAuthDrawer's handleTriggerClick needs a SyntheticEvent purely to capture
   * `e.currentTarget` as the AC10 focus-return target.
   *
   * document.activeElement is deliberately NOT used as a substitute here, even though it could
   * plausibly hold the real clicked row's own link at this exact point in the call stack:
   * useWishlistAuthDrawer.ts's own handleTriggerClick comment already documents exactly why it
   * chose `e.currentTarget` over `document.activeElement` for this identical purpose — "unlike
   * document.activeElement which may still be body on click." Building this on a mechanism that
   * file's own author already rejected for the same job would trade one honest degradation for a
   * silently unreliable one.
   *
   * 1:1 Figma-alignment audit fix, 2026-09-22 (Marcel's own direct report + decision): this used
   * to open the auth drawer without closing the cart first, so the two stacked — unmanaged
   * DOM/paint order, not a deliberate layering, since both use the same `zIndex: 'modal'`. Now
   * closes the cart drawer first (`onClose()`), so the auth drawer opens alone instead. This
   * supersedes this comment's own earlier note (removed here) about focus landing on the
   * still-open cart drawer's own sentinel on close — the cart isn't still open any more, so that
   * particular degradation no longer applies. See `handleAuthSuccess` above for the other half:
   * the cart reopens once the auth flow actually succeeds.
   */
  const openGuestWishlistDrawer = useCallback(() => {
    onClose();
    wishlistAuthDrawer.handleTriggerClick({ currentTarget: document.body } as unknown as SyntheticEvent<HTMLElement>);
  }, [onClose, wishlistAuthDrawer.handleTriggerClick]);

  /* -------------------------------------------------------------------------------------------
   * Pass criterion 3 — real remove/wishlist-move mutations, not stubs.
   * ---------------------------------------------------------------------------------------- */
  const removeItemFromBasketMutation = useShopperBasketsMutation('removeItemFromBasket');
  const updateItemInBasketMutation = useShopperBasketsMutation('updateItemInBasket');
  const customerId = useCustomerId();
  const { data: wishlist } = useWishList();
  const createCustomerProductListItem = useShopperCustomersMutation('createCustomerProductListItem');

  const removeItem = async (itemId?: string): Promise<void> => {
    if (!basket?.basketId || !itemId) return;
    await removeItemFromBasketMutation.mutateAsync({ parameters: { basketId: basket.basketId, itemId } });
    // 1:1 Figma-alignment audit fix, 2026-09-22 — see UseCurrentBasketReturn's own doc above.
    // Fire-and-forget: the header's bag count catching up a beat after this resolves is fine, the
    // removed line's own card is already gone from this drawer regardless.
    void refetchBasket();
  };

  // 1:1 Figma-alignment audit fix, 2026-09-22 — see this file's own module docblock. Mirrors
  // ProductItem's onItemQuantityChange contract exactly: resolve true only on a real, persisted
  // change, so the stepper's own "commit locally only if the mutation succeeded" logic
  // (handleStepperQuantityChange) can't ever show a quantity the basket didn't actually accept.
  const updateItemQuantity = async (itemId: string | undefined, quantity: number): Promise<boolean> => {
    if (!basket?.basketId || !itemId) return false;
    try {
      await updateItemInBasketMutation.mutateAsync({
        parameters: { basketId: basket.basketId, itemId },
        body: { quantity },
      });
      // Fire-and-forget, same reasoning as removeItem above — the stepper's own local state
      // already reflects the new quantity immediately; this only needs to reach the header.
      void refetchBasket();
      return true;
    } catch {
      return false;
    }
  };

  const moveToWishlist = async (productId: string): Promise<WishlistMoveResult> => {
    // Same lookup base product-detail/index.tsx's own handleAddToWishlist uses against
    // wishlist?.customerProductListItems.
    const isAlreadyInWishlist = wishlist?.customerProductListItems?.some(
      (item: { productId?: string }) => item.productId === productId,
    );
    if (isAlreadyInWishlist) {
      return { status: 'already-in-wishlist' };
    }
    if (!wishlist?.id) {
      // useWishList() auto-provisions a wish_list for a first-time registered customer and only
      // resolves it asynchronously (see that hook's own onSuccess) — surfaced as an error rather
      // than silently doing nothing, matching useCartMergeAndCap.ts's own "nothing valid to
      // address a write at" precedent.
      return { status: 'error', error: new Error('cartDrawerContainer: no wishlist available yet.') };
    }
    try {
      await createCustomerProductListItem.mutateAsync({
        parameters: {
          listId: wishlist.id,
          // SDK param widening — useCustomerId returns string | null; onMoveToWishlist is only
          // ever invoked for a registered shopper (ZimmCartItemActions only calls this prop
          // directly when isGuest is false, and the resumed path only fires once isGuest has
          // become false — see usePendingWishlistItem.ts), matching product-detail/index.tsx's
          // own identical cast for the same real precondition.
          customerId: customerId as string,
        },
        body: {
          // NOTE: API does not respect quantity, it always adds 1 — see WISHLIST_ADD_QUANTITY's
          // own comment above.
          quantity: WISHLIST_ADD_QUANTITY,
          productId,
          public: false,
          priority: 1,
          type: 'product',
        },
      });
      return { status: 'success' };
    } catch (error) {
      return { status: 'error', error };
    }
  };

  return (
    <>
      <ZimmCartDrawer
        isOpen={isOpen}
        onClose={onClose}
        itemCount={itemCount}
        finalFocusRef={finalFocusRef}
        // SFCC-317 — wired into its real, intended destination (see that component's own
        // docblock: "provisional placement" on the PDP tab, "until cart drawer ships"). Renders
        // nothing if Contentful has no published `iconAndText`/`benefits` entry — same
        // already-established behaviour as the PDP tab.
        //
        // 1:1 Figma-alignment audit fix, 2026-09-23 (Marcel's direct report): omitted entirely on
        // an empty cart, not just left to render whatever ZimmBenefits itself decides — the empty
        // state has no benefits strip in Figma at all, and `footer` isn't passed a real element
        // in this case so ZimmCartDrawer's own conditional wrapper (index.tsx) skips rendering it
        // too, rather than leaving an empty, still-margined box behind.
        footer={itemCount === 0 ? undefined : <ZimmBenefits />}
      >
        {itemCount === 0 ? (
          <ZimmCartEmptyState onContinueShoppingClick={onClose} />
        ) : (
          <>
            <CartItemsColumn
              productItems={productItems}
              productsById={productsById}
              isProductsLoading={isProductsLoading}
              isGuestState={isGuestState}
              alreadyInWishlistItemIds={alreadyInWishlistItemIds}
              onAlreadyInWishlist={markAlreadyInWishlist}
              onClose={onClose}
              updateItemQuantity={updateItemQuantity}
              removeItem={removeItem}
              moveToWishlist={moveToWishlist}
              openGuestWishlistDrawer={openGuestWishlistDrawer}
            />
            {/* Column 2 (26.875rem desktop track) — the real Figma column also holds a totals
                breakdown, promotion code, and recommended-for-you below this, all still out of
                scope (see this file's own docblock). At/above `xl` this renders as a plain grid
                sibling (the 140px column-gap already separates it from column 1 — no border or
                extra margin needed there). Below `xl`, `body` collapses to a single flex column
                (zimmCartDrawer.css.ts) with no gap of its own between its children — but Figma's
                own tablet frame (node 9323:65993, "Totals-summary") shows this section is NOT
                simply adjacent to the items: it sits 48px below them (Cart Summary's own gap),
                behind a black top border, with its own further 32px of padding before the
                button group starts. Confirmed against the real tablet frame directly, not
                guessed — reproduced here rather than on ZimmCartDrawer itself since it's specific
                to how these two particular children relate, not a generic drawer-body concern.
                1:1 Figma-alignment audit fix, 2026-09-22 (Marcel's direct report) — desktop-only
                `paddingBottom`: the real `Totals-summary` node (9323:95939) carries
                `pb-[var(--alias/space/800,32px)]` on itself, reserved below its content within
                its own column-height-stretched box — confirmed directly against the raw node
                data, not inferred (contrast the items column's own matching value above, which
                *is* inferred). Same var(--zimm-scale-2xl) token as the tablet/mobile
                `paddingTop` above — same 32px value, opposite edge, different breakpoint. */}
            <Box
              sx={{
                borderTop: '1px solid var(--zimm-color-text-default)',
                marginTop: 'var(--zimm-scale-1200)',
                paddingTop: 'var(--zimm-scale-2xl)',
                [`@media (min-width: ${breakpoints.xl})`]: {
                  borderTop: 'none',
                  marginTop: 0,
                  paddingTop: 0,
                  paddingBottom: 'var(--zimm-scale-2xl)',
                },
              }}
            >
              <ZimmCartButtonGroup />
            </Box>
          </>
        )}
      </ZimmCartDrawer>
      <CartWishlistAuthGate wishlistAuthDrawer={wishlistAuthDrawer} />
    </>
  );
};

