  // very first render, rather than staying wrongly locked with no scroll event left to fire.
  const [isLhsAtBottom, setIsLhsAtBottom] = useState(false);

  useEffect(() => {
    if (!scrollAreaEl) return;
    // > 0, not >= some threshold: any real scroll past body's own bottom edge means the footer
    // has started to show. React's own setState bails out when the value hasn't actually
    // changed, so this needs no manual guard against firing on every scroll tick.
    const handleScroll = () => setIsFooterRevealed(scrollAreaEl.scrollTop > 0);
    scrollAreaEl.addEventListener('scroll', handleScroll);
    return () => scrollAreaEl.removeEventListener('scroll', handleScroll);
  }, [scrollAreaEl]);

  // Stable across renders except when isFooterRevealed itself changes — setIsLhsAtBottom is
  // already stable by React's own guarantee, so this only avoids handing the items column a new
  // function/object identity on every unrelated re-render of this component.
  const scrollAreaContextValue = useMemo(
    () => ({ isFooterRevealed, onLhsAtBottomChange: setIsLhsAtBottom }),
    [isFooterRevealed],
  );

  return (
    <ZimmDrawer
      isOpen={isOpen}
      onClose={onClose}
      size="xLarge"
      title={title}
      titleStyle="small"
